//! `POST /playground/generate-schema` — YAML cubes for tables picked on the
//! data-model page.
//!
//! Node.js runs `ScaffoldingTemplate` and can write JavaScript too; this
//! server loads only YAML, so that is the one format it writes. A cube gets a
//! dimension per column whose type maps onto Cube's, and a `count` measure.
//!
//! A file is never overwritten, with one exception. A file whose first line
//! starts with `# Generated by` belongs to a generator that rewrites it (the
//! SofiaDB sync writes one per table). Generating a cube already defined by
//! such a file *adopts* it: its content moves to the model root, comment
//! header dropped, so the user can edit it and the generator, which leaves
//! tables with a cube outside its own directory alone, stops rewriting it.
//! The adopted cube keeps its name, so joins pointing at it still resolve.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use serde::Deserialize;
use serde_json::{json, Value};
use serde_yaml::{Mapping, Value as Yaml};

use crate::error::ApiError;

const GENERATED_MARKER: &str = "# Generated by";

#[derive(Debug, Deserialize)]
pub struct GenerateRequest {
    #[serde(default)]
    pub format: Option<String>,
    /// `[schema, table]` pairs, as the data-model page sends them.
    #[serde(default)]
    pub tables: Vec<(String, String)>,
    #[serde(default, rename = "tablesSchema")]
    pub tables_schema: cubedriver::DatabaseStructure,
}

/// Writes the cubes for `request.tables` under `model_dir`, returning the
/// files written as `{ fileName, content }`, as Node.js does.
///
/// `data_sources` is the configured `(name, type)` list: a schema named
/// `<data source>.<schema>` (how `/playground/db-schema` lists every source
/// but `default`) belongs to that source.
pub fn generate(
    model_dir: &Path,
    data_sources: &[(String, String)],
    request: &GenerateRequest,
) -> Result<Vec<Value>, ApiError> {
    match request.format.as_deref() {
        Some("yaml") => {}
        _ => {
            return Err(ApiError::bad_request(
                "Only YAML data models can be generated: this server loads YAML \
                 and does not run JavaScript.",
            ))
        }
    }
    if request.tables.is_empty() {
        return Err(ApiError::bad_request("No tables selected"));
    }

    let existing = existing_cubes(model_dir);
    let mut taken: BTreeSet<String> = existing.keys().cloned().collect();

    // Everything is decided before anything is written, so one bad table
    // leaves the model as it was.
    let mut plans = Vec::new();
    for (schema, table) in &request.tables {
        let columns = request
            .tables_schema
            .get(schema)
            .and_then(|tables| tables.get(table))
            .ok_or_else(|| ApiError::bad_request(format!("Unknown table {schema}.{table}")))?;

        let (data_source, db_schema) = split_schema(schema, data_sources);
        let name = if data_source == "default" {
            snake(table)
        } else {
            format!("{}_{}", snake(db_schema), snake(table))
        };

        let plan = match existing.get(&name) {
            Some(owner) if owner.generated => Plan::Adopt {
                name: name.clone(),
                from: owner.path.clone(),
            },
            Some(owner) => {
                return Err(ApiError::bad_request(format!(
                    "A cube named {name} already exists in {}",
                    owner
                        .path
                        .strip_prefix(model_dir)
                        .unwrap_or(&owner.path)
                        .display()
                )))
            }
            None if taken.contains(&name) => {
                return Err(ApiError::bad_request(format!(
                    "{schema}.{table} and another selected table both make a cube named {name}"
                )))
            }
            None => {
                let db_type = data_sources
                    .iter()
                    .find(|(n, _)| n == data_source)
                    .map(|(_, t)| t.as_str())
                    .unwrap_or("");
                Plan::Write {
                    name: name.clone(),
                    content: cube_yaml(&name, data_source, db_type, db_schema, table, columns)?,
                }
            }
        };
        taken.insert(name.clone());

        let target = model_dir.join(format!("{}.yml", plan.name()));
        if target.exists() && !matches!(&plan, Plan::Adopt { from, .. } if *from == target) {
            return Err(ApiError::bad_request(format!(
                "{} already exists",
                target.file_name().unwrap_or_default().to_string_lossy()
            )));
        }
        plans.push((plan, target));
    }

    std::fs::create_dir_all(model_dir).map_err(io_error)?;
    let mut files = Vec::new();
    for (plan, target) in plans {
        let content = match &plan {
            Plan::Write { content, .. } => content.clone(),
            Plan::Adopt { from, .. } => {
                strip_header(&std::fs::read_to_string(from).map_err(io_error)?)
            }
        };

        // Written under a name the loader skips, then moved into place, so
        // the model is never read with a half-written file.
        let tmp = target.with_extension("yml.tmp");
        std::fs::write(&tmp, &content).map_err(io_error)?;
        if let Plan::Adopt { from, .. } = &plan {
            if *from != target {
                std::fs::remove_file(from).map_err(io_error)?;
            }
        }
        std::fs::rename(&tmp, &target).map_err(io_error)?;

        files.push(json!({
            "fileName": target.strip_prefix(model_dir).unwrap_or(&target).to_string_lossy(),
            "content": content,
        }));
    }

    Ok(files)
}

enum Plan {
    Write { name: String, content: String },
    Adopt { name: String, from: PathBuf },
}

impl Plan {
    fn name(&self) -> &str {
        match self {
            Plan::Write { name, .. } | Plan::Adopt { name, .. } => name,
        }
    }
}

struct Owner {
    path: PathBuf,
    /// The file is a generator's, and holds this cube alone.
    generated: bool,
}

/// Every cube and view name defined under `dir`, with the file defining it.
fn existing_cubes(dir: &Path) -> BTreeMap<String, Owner> {
    let mut out = BTreeMap::new();
    walk(dir, &mut out);
    out
}

fn walk(dir: &Path, out: &mut BTreeMap<String, Owner>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            walk(&path, out);
            continue;
        }
        if !matches!(
            path.extension().and_then(|e| e.to_str()),
            Some("yml") | Some("yaml")
        ) {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(&path) else {
            continue;
        };
        let Ok(doc) = serde_yaml::from_str::<Yaml>(&text) else {
            continue;
        };

        let mut names = Vec::new();
        for kind in ["cubes", "views"] {
            if let Some(items) = doc.get(kind).and_then(Yaml::as_sequence) {
                names.extend(
                    items
                        .iter()
                        .filter_map(|item| item.get("name").and_then(Yaml::as_str))
                        .map(str::to_string),
                );
            }
        }
        let generated = text.starts_with(GENERATED_MARKER) && names.len() == 1;
        for name in names {
            out.insert(
                name,
                Owner {
                    path: path.clone(),
                    generated,
                },
            );
        }
    }
}

/// `sofiadb.dfos` → `("sofiadb", "dfos")` when `sofiadb` is a configured
/// source other than `default`; anything else is a `default` schema.
fn split_schema<'a>(schema: &'a str, data_sources: &'a [(String, String)]) -> (&'a str, &'a str) {
    if let Some((source, rest)) = schema.split_once('.') {
        if source != "default" && data_sources.iter().any(|(n, _)| n == source) {
            return (source, rest);
        }
    }
    ("default", schema)
}

fn cube_yaml(
    name: &str,
    data_source: &str,
    db_type: &str,
    schema: &str,
    table: &str,
    columns: &[cubedriver::SchemaColumn],
) -> Result<String, ApiError> {
    let mut cube = Mapping::new();
    cube.insert("name".into(), name.into());
    if data_source != "default" {
        cube.insert("data_source".into(), data_source.into());
    }
    cube.insert(
        "sql_table".into(),
        format!("{}.{}", quote(db_type, schema), quote(db_type, table)).into(),
    );

    let mut members = BTreeSet::from(["count".to_string()]);
    let mut dimensions = Vec::new();
    for column in columns {
        let Some(cube_type) = cube_type(&column.type_) else {
            continue;
        };
        let mut member = snake(&column.name);
        let base = member.clone();
        let mut n = 2;
        while !members.insert(member.clone()) {
            member = format!("{base}_{n}");
            n += 1;
        }

        let mut dimension = Mapping::new();
        dimension.insert("name".into(), member.into());
        dimension.insert(
            "sql".into(),
            format!("{{CUBE}}.{}", quote(db_type, &column.name)).into(),
        );
        dimension.insert("type".into(), cube_type.into());
        if column.attributes.iter().any(|a| a == "primaryKey") {
            dimension.insert("primary_key".into(), true.into());
        }
        dimensions.push(Yaml::Mapping(dimension));
    }
    if !dimensions.is_empty() {
        cube.insert("dimensions".into(), Yaml::Sequence(dimensions));
    }

    let mut count = Mapping::new();
    count.insert("name".into(), "count".into());
    count.insert("type".into(), "count".into());
    cube.insert(
        "measures".into(),
        Yaml::Sequence(vec![Yaml::Mapping(count)]),
    );

    let mut doc = Mapping::new();
    doc.insert("cubes".into(), Yaml::Sequence(vec![Yaml::Mapping(cube)]));
    serde_yaml::to_string(&doc).map_err(|e| ApiError::bad_request(e.to_string()))
}

/// Cube's type for a raw database type, or `None` for one it has no type for
/// (arrays, maps, JSON, ...), which is left out.
fn cube_type(raw: &str) -> Option<&'static str> {
    let mut t = raw.trim().to_ascii_lowercase();
    // ClickHouse wrappers that do not change what the value is.
    for wrapper in ["nullable(", "lowcardinality("] {
        while let Some(inner) = t.strip_prefix(wrapper) {
            t = inner.strip_suffix(')').unwrap_or(inner).to_string();
        }
    }
    let word = t
        .split(|c: char| c == '(' || c.is_whitespace())
        .next()
        .unwrap_or("");

    if word.starts_with("array")
        || word.starts_with("map")
        || word.starts_with("tuple")
        || word.starts_with("json")
        || word.ends_with("[]")
    {
        return None;
    }
    if word.starts_with("bool") {
        return Some("boolean");
    }
    if word.starts_with("date") || word.starts_with("time") {
        return Some("time");
    }
    let numeric = [
        "int",
        "uint",
        "integer",
        "smallint",
        "bigint",
        "tinyint",
        "mediumint",
        "float",
        "double",
        "decimal",
        "numeric",
        "real",
        "number",
        "money",
        "serial",
        "bigserial",
    ];
    if numeric.iter().any(|n| {
        word == *n || (word.starts_with(n) && word[n.len()..].chars().all(|c| c.is_ascii_digit()))
    }) {
        return Some("number");
    }
    Some("string")
}

/// Leaves a plain identifier bare, quotes anything else the way the
/// database expects.
fn quote(db_type: &str, ident: &str) -> String {
    let plain = ident
        .chars()
        .next()
        .is_some_and(|c| c.is_ascii_lowercase() || c == '_')
        && ident
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    if plain {
        return ident.to_string();
    }
    match db_type {
        "clickhouse" | "mysql" | "databricks-jdbc" | "bigquery" => {
            format!("`{}`", ident.replace('`', "\\`"))
        }
        _ => format!("\"{}\"", ident.replace('"', "\"\"")),
    }
}

/// `fiberCableId` → `fiber_cable_id`, matching the SofiaDB sync's names.
fn snake(name: &str) -> String {
    let mut out = String::new();
    let mut prev: Option<char> = None;
    for c in name.chars() {
        if c.is_ascii_uppercase()
            && prev.is_some_and(|p| p.is_ascii_lowercase() || p.is_ascii_digit())
        {
            out.push('_');
        }
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
        } else if !out.ends_with('_') {
            out.push('_');
        }
        prev = Some(c);
    }
    let out = out.trim_matches('_').to_string();
    match out.chars().next() {
        None => "col".to_string(),
        Some(c) if c.is_ascii_digit() => format!("c_{out}"),
        Some(_) => out,
    }
}

/// The file without its leading comment lines (the generator's "do not
/// edit" note, which stops being true once the file is adopted).
fn strip_header(text: &str) -> String {
    text.lines()
        .skip_while(|line| line.starts_with('#'))
        .collect::<Vec<_>>()
        .join("\n")
        + "\n"
}

fn io_error(e: std::io::Error) -> ApiError {
    tracing::warn!(error = %e, "cannot write the generated data model");
    ApiError::new(
        axum::http::StatusCode::INTERNAL_SERVER_ERROR,
        format!("Cannot write the data model: {e}"),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn types_map_onto_cubes() {
        assert_eq!(cube_type("Nullable(Int64)"), Some("number"));
        assert_eq!(
            cube_type("LowCardinality(Nullable(String))"),
            Some("string")
        );
        assert_eq!(cube_type("DateTime64(3, 'UTC')"), Some("time"));
        assert_eq!(cube_type("timestamp without time zone"), Some("time"));
        assert_eq!(cube_type("double precision"), Some("number"));
        assert_eq!(cube_type("Decimal(10, 2)"), Some("number"));
        assert_eq!(cube_type("Bool"), Some("boolean"));
        assert_eq!(cube_type("UUID"), Some("string"));
        assert_eq!(cube_type("point"), Some("string"));
        assert_eq!(cube_type("Array(Int32)"), None);
        assert_eq!(cube_type("integer[]"), None);
    }

    #[test]
    fn names_are_snake_case() {
        assert_eq!(snake("fiberCableId"), "fiber_cable_id");
        assert_eq!(snake("Line Items"), "line_items");
        assert_eq!(snake("2024sales"), "c_2024sales");
    }

    #[test]
    fn only_odd_identifiers_are_quoted() {
        assert_eq!(quote("postgres", "orders"), "orders");
        assert_eq!(quote("postgres", "Orders"), "\"Orders\"");
        assert_eq!(quote("clickhouse", "Fiber Cable"), "`Fiber Cable`");
    }

    #[test]
    fn a_prefixed_schema_belongs_to_its_source() {
        let sources = vec![
            ("default".to_string(), "postgres".to_string()),
            ("sofiadb".to_string(), "clickhouse".to_string()),
        ];
        assert_eq!(split_schema("sofiadb.dfos", &sources), ("sofiadb", "dfos"));
        assert_eq!(split_schema("public", &sources), ("default", "public"));
        assert_eq!(
            split_schema("my.schema", &sources),
            ("default", "my.schema")
        );
    }
}
